// src/lib/date.ts
function localIsoDay(plusDays = 0) {
  const d = /* @__PURE__ */ new Date();
  d.setDate(d.getDate() + plusDays);
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
}

